import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const E2E_API_PORT = 4310;
export const E2E_WEB_PORT = 3310;
export const E2E_BASE_URL = `http://localhost:${E2E_WEB_PORT}`;

/** Secrets and E2E database URLs from apps/api/.env (generated by `pnpm setup`). */
export function apiDotEnv(): Record<string, string> {
  const file = fileURLToPath(new URL('../../api/.env', import.meta.url));
  if (!existsSync(file)) throw new Error('apps/api/.env missing — run `pnpm setup` first.');
  const out: Record<string, string> = {};
  for (const line of readFileSync(file, 'utf8').split(/\r?\n/)) {
    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line);
    if (m) out[m[1]!] = m[2]!;
  }
  return out;
}

/** Environment for the API instance under test: isolated psacc_e2e database, APP_ENV=test. */
export const E2E_GATEWAY_PORT = 8543;

export function e2eApiEnv(): Record<string, string> {
  const f = apiDotEnv();
  return {
    APP_ENV: 'test',
    HOST: '127.0.0.1',
    PORT: String(E2E_API_PORT),
    LOG_LEVEL: 'warn',
    TRUST_PROXY: 'loopback',
    APP_ALLOWED_ORIGINS: `http://localhost:${E2E_WEB_PORT},http://127.0.0.1:${E2E_WEB_PORT}`,
    OPENAPI_ENABLED: 'false',
    // Own gateway port so it never collides with a dev gateway on :8443.
    AGENT_GATEWAY_ENABLED: 'true',
    AGENT_GATEWAY_HOST: '127.0.0.1',
    AGENT_GATEWAY_URL: `https://127.0.0.1:${E2E_GATEWAY_PORT}`,
    AUTH_MFA_REQUIRED: 'false',
    LOGIN_RATE_LIMIT_PER_MINUTE: '300',
    RATE_LIMIT_PER_MINUTE: '5000',
    CSRF_SECRET: f.CSRF_SECRET!,
    DATA_ENCRYPTION_KEY: f.DATA_ENCRYPTION_KEY!,
    DATABASE_URL: f.E2E_DATABASE_URL!,
    MIGRATION_DATABASE_URL: f.E2E_MIGRATION_DATABASE_URL!,
    SEED_DEFAULT_PASSWORD: f.SEED_DEFAULT_PASSWORD!,
  };
}

export const SEED_PASSWORD = () => apiDotEnv().SEED_DEFAULT_PASSWORD!;
